-- C1. TILE — corrections de confidentialité + événements complémentaires
-- ===========================================================================

-- B (confidentialité) : reformulation sans stack — Flutter/Firebase/React ne

-- peuvent pas apparaître dans les contenus publics (directive CTO §7).

UPDATE product_milestones SET title = 'Lancement du développement',
  description_md = 'Posé dès l''origine : une application multiplateforme — Android, iOS et Web/PWA — pilotée depuis une console d''administration dédiée. Cette base a été conservée et enrichie depuis, jamais remplacée.',
  source_label = 'Fondateur — mission CTO N°2, 10/11/2026 · Archives produit (architecture conservée)',
  updated_at = datetime('now')
WHERE slug = 'tile-mil-02' AND (title LIKE '%Flutter%' OR description_md LIKE '%Flutter%' OR description_md LIKE '%Firebase%');

UPDATE product_milestones SET
  description_md = 'Le « FINAL RELEASE REPORT (V1.0 LOCK) » du 17 juillet 2026 atteste tous les critères de fin : analyse de qualité du code sans erreur, console d''administration compilée, composants d''interface dédoublonnés (avatars, sources utilisateur), trois fils validés (Certifié, Global, Vidéo), backend gelé. Cinq commits, 333 lignes nettes supprimées.',
  updated_at = datetime('now')
WHERE slug = 'tile-mil-04' AND description_md LIKE '%Flutter%';

UPDATE product_milestones SET
  description_md = 'Octobre 2026 : consolidation de l''espace entreprise et de l''Explorer knowledge (4 octobre), activation de l''authentification cloud sécurisée (10 octobre), studio de création avancé (11 octobre), parité PWA/Android/iOS (4 octobre), préparation du dossier App Store (5-10 octobre).',
  updated_at = datetime('now')
WHERE slug = 'tile-mil-06' AND description_md LIKE '%Firebase%';

-- Correction par preuve retrouvée : le lancement public (article du 22/04/2026 +

-- journal de versions de la fiche) précise la production PWA d'avril 2026.

UPDATE product_milestones SET
  occurred_on = '2026-04', date_precision = 'archives', confidence = 'haute',
  description_md = 'Tile est ouvert au public en Progressive Web App : article d''annonce du 22 avril 2026 (« Tile, le Réseau du Progrès ») et journal de versions de la fiche (« v1.0 — avril 2026 : vidéos, vocaux, stories, trois flux et messagerie privée ») attestent le lancement public. Le repère fondateur « en production depuis environ six mois » recoupe cette date.',
  source_label = 'Archives éditoriales : article « tile-lancement-reseau-progres », 22/04/2026 · versions de la fiche produit',
  updated_at = datetime('now')
WHERE slug = 'tile-mil-03' AND occurred_on = '2026-05' AND date_precision = 'approximative';

-- Correction de la version 1.0 : reformulation sans stack (capacités uniquement).

UPDATE product_versions SET
  summary = 'Verrouillage de la release 1.0 (« V1.0 LOCK ») : tous les critères de fin attestés — analyse de qualité du code sans erreur, console d''administration compilée, trois fils validés (Certifié, Global, Vidéo), backend gelé.',
  updated_at = datetime('now')
WHERE slug = 'tile-ver-1-0' AND (summary LIKE '%Flutter%' OR summary LIKE '%Firebase%');

