  version_ref = '1.0',
  updated_at = datetime('now')
WHERE slug = 'qrfad-mil-03' AND occurred_on = '2022' AND date_precision = 'estimee';

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'qrfad', 'qrfad-hist-01', 'cadrage', 'Réflexion initiale : le problème des menus papier à Bamako', 'Avant tout développement, le constat fondateur : les menus papier vieillissent, coûtent cher à réimprimer et coupent le restaurant de ses clients. L''objectif formulé dès 2019-2020 : un menu numérique accessible par QR code, sans application pour le client, gérable par le restaurateur.', '2020', 'approximative', NULL, NULL, NULL, '[]', 'Fondateur — mission CTO N°2, 10/11/2026 · récits éditoriaux QRFAD (2021-2026)', 'moyenne', 2, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'qrfad-hist-01');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'qrfad', 'qrfad-hist-02', 'conception', 'Conception du produit : menus, plats, prix, photos — sans application', 'La conception cible le chemin le plus court : le client scanne un QR code sur la table, le restaurateur met à jour plats, prix et photos depuis une console simple. Le « sans application » pour le client est une décision de cadrage structurante, maintenue depuis.', '2020', 'approximative', NULL, NULL, NULL, '[]', 'Fondateur — mission CTO N°2, 10/11/2026 · journal de versions de la fiche (v1.0)', 'moyenne', 3, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'qrfad-hist-02');

