-- ===========================================================================
-- C6. CLOUDaf — parcours complet sur repères fondateur + versions v1.0/v1.1/v1.2
-- ===========================================================================

-- Repères fondateur (9-10/11/2026) : conception envisagée depuis ~3 ans ;

-- production depuis ~8 mois (≈ mars 2026) ; dernière mise à jour ~1 semaine

-- avant le 9 novembre 2026 (≈ 2 novembre 2026). Versions v1.0 (juin 2026),

-- v1.1 (août 2026), v1.2 (octobre 2026) attestées par le journal de la fiche

-- et les articles datés. CLOUDaf est un produit indépendant — aucun recoupement

-- avec les parcours des autres produits.

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-01', 'cadrage', 'Formalisation du concept : le double éditeur no-code + code', 'Après des années d''exploitation de ses propres plateformes, le constat fondateur : le plus dur n''est pas d''écrire une application, c''est tout ce qui l''entoure. Le concept formalisé dès 2023 : un double éditeur no-code + code synchronisé, pour commencer en glisser-déposer et descendre au code quand on le décide.', '2023', 'approximative', NULL, NULL, NULL, '[]', 'Repère fondateur (« conception envisagée depuis environ trois ans », 10/11/2026) · article « cloudaf-lancement » (03/06/2026)', 'moyenne', 2, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-01');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-02', 'conception', 'Conception : Studio Builder, Agent IA, déploiement en un clic', 'Le périmètre de conception fixe les trois piliers : un Studio Builder visuel (bibliothèque de blocs, canvas glisser-déposer, inspecteur, thèmes), une IA intégrée qui devient un Agent à outils audités, et un déploiement en un clic avec SSL automatique, CDN mondial et domaine personnalisé.', '2023', 'approximative', NULL, NULL, NULL, '[]', 'Article « cloudaf-lancement » (03/06/2026) — périmètre initialement prévu', 'moyenne', 3, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-02');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-03', 'cadrage', 'Premiers objectifs et modèle d''offres', 'Les objectifs de premier jour : créer un projet, le déployer, le surveiller — sans équipe d''infrastructure. Le modèle d''offres est cadré : Free (0 €), Pro (29 €/mois), Enterprise (99 €/mois), avec un Store pour vendre ses propres templates.', '2024', 'approximative', NULL, NULL, NULL, '[]', 'Fiche produit CLOUDaf (offres) · article « cloudaf-agent-ia » (08/10/2026)', 'moyenne', 4, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-03');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-04', 'tests', 'Validation : parcours complet projet → build → déploiement', 'Les phases de validation couvrent le parcours réel d''un projet : création depuis le Studio Builder, builds, déploiement avec SSL et domaine, monitoring. Les rapports de tests datés restent à retrouver — statut « à confirmer ».', NULL, 'inconnue', NULL, NULL, NULL, '[]', 'Reconstitution : parcours validé lors de la mise en production — rapports à retrouver', 'faible', 5, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-04');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-05', 'premiere_production', 'Mise en production de la plateforme (repère : ≈ mars 2026)', 'Selon le repère fondateur (« en production depuis environ huit mois » au 9 novembre 2026), la plateforme entre en production vers mars 2026. Cette date d''exploitation précède le lancement public de juin 2026 : deux étapes distinctes — mise en service puis ouverture officielle.', '2026-03', 'approximative', NULL, NULL, NULL, '[]', 'Fondateur — mission CTO N°2, 10/11/2026 (« production depuis environ 8 mois »)', 'moyenne', 6, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-05');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-06', 'annonce', 'Lancement public v1.0 : « Créez. Déployez. Scalez. »', 'Le 3 juin 2026, l''article « CloudAf : créer, déployer et scaler sans se soucier de l''infrastructure » officialise le lancement : double éditeur no-code + code, IA intégrée, Studio Builder et déploiement en un clic avec SSL, CDN et domaine personnalisé. Offres Free, Pro (29 €/mois), Enterprise (99 €/mois).', '2026-06-03', 'exacte', '1.0', (SELECT id FROM product_versions WHERE slug = 'cloudaf-ver-1-0'), 'cloudaf-lancement', '[{"key":"/assets/images/products/cloudaf-desktop-01.jpg","type":"desktop","alt":"CloudAf — landing « Créez. Déployez. Scalez. »"}, {"key":"/assets/images/products/cloudaf-desktop-08.jpg","type":"desktop","alt":"CloudAf — accueil du dashboard"}]', 'Archives éditoriales : article « cloudaf-lancement » (03/06/2026) · journal de versions de la fiche (v1.0 — juin 2026)', 'haute', 7, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-06');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-07', 'premier_utilisateur', 'Premiers créateurs sur la plateforme', 'À l''ouverture publique de juin 2026, les premiers créateurs démarrent leurs projets — le projet réel « signature--lectroniq » visible dans la démonstration du 10 novembre 2026 illustre des usages en production. Les volumes et dates exactes restent à confirmer.', '2026-06', 'approximative', NULL, NULL, NULL, '[]', 'Repère : lancement public (03/06/2026) · démonstration cloudaf.net (10/11/2026) — volumes à confirmer', 'faible', 8, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-07');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-08', 'mise_a_jour', 'v1.1 (août 2026) : Agent CloudAf et Studio Builder complet', 'Deuxième mise à jour majeure (août 2026) : l''Agent CloudAf discute du projet, le comprend et agit via des outils audités — code, builds, déploiements, ressources — et le Studio Builder s''complete : bibliothèque de blocs, canvas glisser-déposer, inspecteur, thèmes.', '2026-08', 'approximative', '1.1', (SELECT id FROM product_versions WHERE slug = 'cloudaf-ver-1-1'), NULL, '[]', 'Journal de versions de la fiche produit (v1.1 — août 2026)', 'moyenne', 9, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-08');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-09', 'annonce', 'Annonce : « L''Agent CloudAf passe à l''action » — et le Store ouvre', 'Le 8 octobre 2026, l''article « L''Agent CloudAf : l''IA qui construit votre projet avec vous » officialise la v1.2 : l''Agent opère de véritables outils audités et le CloudAf Store ouvre — templates en crédits, revente de ses propres projets. C''est la troisième mise à jour majeure en cinq mois (v1.0 juin, v1.1 août, v1.2 octobre).', '2026-10-08', 'exacte', '1.2', (SELECT id FROM product_versions WHERE slug = 'cloudaf-ver-1-2'), 'cloudaf-agent-ia', '[{"key":"/assets/images/products/cloudaf-desktop-12.jpg","type":"desktop","alt":"CloudAf — lAgent assiste le développeur dans léditeur"}, {"key":"/assets/images/products/cloudaf-desktop-15.jpg","type":"desktop","alt":"CloudAf Store — templates prêts à lemploi"}]', 'Archives éditoriales : article « cloudaf-agent-ia » (08/10/2026) · journal de versions de la fiche (v1.2 — octobre 2026)', 'haute', 10, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-09');

INSERT INTO product_milestones (product_slug, slug, kind, title, description_md, occurred_on, date_precision, version_ref, version_id, article_slug, media_json, source_label, confidence, sort_order, status) SELECT 'cloudaf', 'cloudaf-hist-10', 'derniere_evolution', 'Mise à jour de début novembre 2026 (repère : ≈ 2 novembre 2026)', 'Dernière mise à jour annoncée environ une semaine avant le 9 novembre 2026 (repère fondateur : ≈ 2 novembre 2026). Le périmètre exact de cette mise à jour reste à confirmer par le fondateur — aucune fonctionnalité n''est attribuée sans preuve.', '2026-11-02', 'approximative', NULL, NULL, NULL, '[]', 'Fondateur — mission CTO N°2, 10/11/2026 (« dernière mise à jour ~1 semaine avant le 9/11 »)', 'moyenne', 11, 'publie' WHERE NOT EXISTS (SELECT 1 FROM product_milestones WHERE slug = 'cloudaf-hist-10');

